from typing import Optional

from .fraud_detector import is_description_suspicious_openai

logger = logging.getLogger(__name__)


class DescriptionRiskAdapter:
    """Adapter for checking if a description seems suspicious.

    This provides a seam to plug in different implementations (mock, stub, or
    different providers) without changing business logic.
    """

    def __init__(self, provider: str = "openai", model: str = "gpt-4o"):
        self.provider = provider
        self.model = model

    def is_suspicious(self, description: str) -> bool:
        if not description:
            return False
        if self.provider == "openai":
            return is_description_suspicious_openai(description, model=self.model)
        logger.warning("Unknown description risk provider: %s", self.provider)
        return False
